import{a as e,i as t,r as n,t as r}from"./app-Dkwa1Gla.js";var i=JSON.parse(`{"path":"/%E7%AC%AC11%E7%AB%A0%20%E9%A1%B9%E7%9B%AE%E6%88%90%E6%9C%AC%E7%AE%A1%E7%90%86/11.3%20%E6%88%90%E6%9C%AC%E6%8E%A7%E5%88%B6.html","title":"11.3 成本控制","lang":"zh-CN","frontmatter":{},"git":{},"filePathRelative":"第11章 项目成本管理/11.3 成本控制.md"}`),a={name:`11.3 成本控制.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<h1 id="_11-3-成本控制" tabindex="-1"><a class="header-anchor" href="#_11-3-成本控制"><span>11.3 成本控制</span></a></h1><h2 id="定义" tabindex="-1"><a class="header-anchor" href="#定义"><span>定义</span></a></h2><p>成本控制是指监控项目成本，管理成本偏差，确保项目在预算内完成的过程。</p><h2 id="成本控制的目标" tabindex="-1"><a class="header-anchor" href="#成本控制的目标"><span>成本控制的目标</span></a></h2><h3 id="_1-监控成本绩效" tabindex="-1"><a class="header-anchor" href="#_1-监控成本绩效"><span>1. 监控成本绩效</span></a></h3><ul><li>跟踪实际成本支出</li><li>对比实际成本与成本基准</li></ul><h3 id="_2-管理成本偏差" tabindex="-1"><a class="header-anchor" href="#_2-管理成本偏差"><span>2. 管理成本偏差</span></a></h3><ul><li>识别成本偏差</li><li>分析偏差原因</li></ul><h3 id="_3-确保预算遵守" tabindex="-1"><a class="header-anchor" href="#_3-确保预算遵守"><span>3. 确保预算遵守</span></a></h3><ul><li>确保项目在预算内完成</li><li>避免成本超支</li></ul><h3 id="_4-预测项目成本" tabindex="-1"><a class="header-anchor" href="#_4-预测项目成本"><span>4. 预测项目成本</span></a></h3><ul><li>预测项目最终成本</li><li>及时采取纠正措施</li></ul><h2 id="成本控制方法" tabindex="-1"><a class="header-anchor" href="#成本控制方法"><span>成本控制方法</span></a></h2><h3 id="_1-挣值管理-evm" tabindex="-1"><a class="header-anchor" href="#_1-挣值管理-evm"><span>1. 挣值管理（EVM）</span></a></h3><ul><li><strong>计划值（PV）</strong>：计划完成工作的预算成本</li><li><strong>挣值（EV）</strong>：实际完成工作的预算成本</li><li><strong>实际成本（AC）</strong>：实际完成工作的实际成本</li></ul><h3 id="_2-偏差分析" tabindex="-1"><a class="header-anchor" href="#_2-偏差分析"><span>2. 偏差分析</span></a></h3><ul><li><strong>成本偏差（CV）</strong>：EV - AC</li><li><strong>进度偏差（SV）</strong>：EV - PV</li><li><strong>成本绩效指数（CPI）</strong>：EV / AC</li><li><strong>进度绩效指数（SPI）</strong>：EV / PV</li></ul><h3 id="_3-成本预测" tabindex="-1"><a class="header-anchor" href="#_3-成本预测"><span>3. 成本预测</span></a></h3><ul><li><strong>完工估算（EAC）</strong>：预测项目完工时的总成本</li><li><strong>完工尚需估算（ETC）</strong>：预测完成剩余工作所需的成本</li></ul><h2 id="成本控制流程" tabindex="-1"><a class="header-anchor" href="#成本控制流程"><span>成本控制流程</span></a></h2><h3 id="_1-监控成本支出" tabindex="-1"><a class="header-anchor" href="#_1-监控成本支出"><span>1. 监控成本支出</span></a></h3><ul><li>收集实际成本数据</li><li>记录成本支出情况</li></ul><h3 id="_2-对比成本基准" tabindex="-1"><a class="header-anchor" href="#_2-对比成本基准"><span>2. 对比成本基准</span></a></h3><ul><li>对比实际成本与成本基准</li><li>计算成本偏差</li></ul><h3 id="_3-分析偏差原因" tabindex="-1"><a class="header-anchor" href="#_3-分析偏差原因"><span>3. 分析偏差原因</span></a></h3><ul><li>分析偏差产生的原因</li><li>评估偏差的影响</li></ul><h3 id="_4-采取纠正措施" tabindex="-1"><a class="header-anchor" href="#_4-采取纠正措施"><span>4. 采取纠正措施</span></a></h3><ul><li>根据偏差情况采取措施</li><li>调整成本计划或资源分配</li></ul><h3 id="_5-更新成本基准" tabindex="-1"><a class="header-anchor" href="#_5-更新成本基准"><span>5. 更新成本基准</span></a></h3><ul><li>如果偏差较大，更新成本基准</li><li>获得相关方批准</li></ul><h2 id="挣值管理指标" tabindex="-1"><a class="header-anchor" href="#挣值管理指标"><span>挣值管理指标</span></a></h2><h3 id="成本偏差-cv" tabindex="-1"><a class="header-anchor" href="#成本偏差-cv"><span>成本偏差（CV）</span></a></h3><ul><li><strong>公式</strong>：CV = EV - AC</li><li><strong>解读</strong>：CV &gt; 0 表示成本节约，CV &lt; 0 表示成本超支</li></ul><h3 id="进度偏差-sv" tabindex="-1"><a class="header-anchor" href="#进度偏差-sv"><span>进度偏差（SV）</span></a></h3><ul><li><strong>公式</strong>：SV = EV - PV</li><li><strong>解读</strong>：SV &gt; 0 表示进度提前，SV &lt; 0 表示进度落后</li></ul><h3 id="成本绩效指数-cpi" tabindex="-1"><a class="header-anchor" href="#成本绩效指数-cpi"><span>成本绩效指数（CPI）</span></a></h3><ul><li><strong>公式</strong>：CPI = EV / AC</li><li><strong>解读</strong>：CPI &gt; 1 表示成本绩效好，CPI &lt; 1 表示成本绩效差</li></ul><h3 id="进度绩效指数-spi" tabindex="-1"><a class="header-anchor" href="#进度绩效指数-spi"><span>进度绩效指数（SPI）</span></a></h3><ul><li><strong>公式</strong>：SPI = EV / PV</li><li><strong>解读</strong>：SPI &gt; 1 表示进度绩效好，SPI &lt; 1 表示进度绩效差</li></ul><h2 id="成本控制的注意事项" tabindex="-1"><a class="header-anchor" href="#成本控制的注意事项"><span>成本控制的注意事项</span></a></h2><h3 id="_1-及时监控" tabindex="-1"><a class="header-anchor" href="#_1-及时监控"><span>1. 及时监控</span></a></h3><ul><li>定期监控成本支出</li><li>及时发现偏差</li></ul><h3 id="_2-分析根本原因" tabindex="-1"><a class="header-anchor" href="#_2-分析根本原因"><span>2. 分析根本原因</span></a></h3><ul><li>深入分析偏差原因</li><li>采取针对性措施</li></ul><h3 id="_3-协调其他目标" tabindex="-1"><a class="header-anchor" href="#_3-协调其他目标"><span>3. 协调其他目标</span></a></h3><ul><li>平衡成本、进度和质量</li><li>避免牺牲质量换取成本节约</li></ul><h2 id="关键考点" tabindex="-1"><a class="header-anchor" href="#关键考点"><span>关键考点</span></a></h2><ol><li><strong>挣值管理的指标</strong></li><li><strong>成本偏差的计算方法</strong></li><li><strong>成本控制流程</strong></li></ol><h2 id="记忆口诀" tabindex="-1"><a class="header-anchor" href="#记忆口诀"><span>记忆口诀</span></a></h2><p>挣值分析偏差预测，成本控制三方法，CV SV CPI SPI要记清</p><h2 id="典型例题" tabindex="-1"><a class="header-anchor" href="#典型例题"><span>典型例题</span></a></h2><p><strong>例题</strong>：成本绩效指数（CPI）大于1表示什么？ A. 成本超支 B. 成本节约 C. 进度提前 D. 进度落后</p><p><strong>答案</strong>：B</p><p><strong>解析</strong>：CPI = EV / AC，当CPI &gt; 1时，说明挣值大于实际成本，即成本节约。</p>`,54)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};